import{ar as s,as as a,at as p,au as t}from"./app-CUiZF7NJ.js";const e={};function o(l,n){return t(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="六、对象-object" tabindex="-1"><a class="header-anchor" href="#六、对象-object"><span>六、对象（Object）</span></a></h1><h2 id="_6-1-数据类型回顾" tabindex="-1"><a class="header-anchor" href="#_6-1-数据类型回顾"><span>6.1 数据类型回顾</span></a></h2><p>JavaScript 中的数据类型分为两大类：</p><div class="language-txt" data-highlighter="prismjs" data-ext="txt"><pre><code class="language-txt"><span class="line">┌─────────────────────────────────────────────────────────────┐</span>
<span class="line">│                    JavaScript 数据类型                       │</span>
<span class="line">├───────────────────────────┬─────────────────────────────────┤</span>
<span class="line">│     原始值（7 种）         │        对象（引用类型）           │</span>
<span class="line">├───────────────────────────┼─────────────────────────────────┤</span>
<span class="line">│  Number    │  数值         │  Object    │  普通对象          │</span>
<span class="line">│  BigInt    │  大整数       │  Array     │  数组              │</span>
<span class="line">│  String    │  字符串       │  Function  │  函数              │</span>
<span class="line">│  Boolean   │  布尔值       │  Date      │  日期              │</span>
<span class="line">│  Null      │  空值         │  RegExp    │  正则              │</span>
<span class="line">│  Undefined │  未定义       │  Error     │  错误              │</span>
<span class="line">│  Symbol    │  符号         │  ...       │  其他              │</span>
<span class="line">├───────────────────────────┴─────────────────────────────────┤</span>
<span class="line">│  原始值不可变（Immutable），对象可变（Mutable）                │</span>
<span class="line">│  原始值存储在栈中，对象存储在堆中，变量存的是地址               │</span>
<span class="line">└─────────────────────────────────────────────────────────────┘</span>
<span class="line"></span></code></pre></div><table><thead><tr><th>特征</th><th>原始值（Primitive）</th><th>对象（Object）</th></tr></thead><tbody><tr><td><strong>存储内容</strong></td><td>简单的数据值</td><td>多个数据的集合</td></tr><tr><td><strong>数据量</strong></td><td>只能表示一个值</td><td>可以存储多个不同类型的数据</td></tr><tr><td><strong>典型场景</strong></td><td>数字、字符串、布尔值等</td><td>表示复杂实体（如&quot;人&quot;的信息）</td></tr><tr><td><strong>可变性</strong></td><td><strong>不可变</strong></td><td><strong>可变</strong></td></tr></tbody></table><blockquote><p><strong>问题引入</strong>：如果需要在程序中表示一个人的信息（姓名、年龄、性别、地址等），原始值无法满足需求。对象正是为了解决这个问题而诞生的。</p></blockquote><h2 id="_6-2-认识对象" tabindex="-1"><a class="header-anchor" href="#_6-2-认识对象"><span>6.2 认识对象</span></a></h2><p><strong>对象（Object）</strong> 是 JavaScript 中的一种<strong>复合数据类型</strong>，它相当于一个<strong>容器</strong>，可以在其中存储各种不同类型的数据（称为<strong>属性</strong>）。</p><h3 id="_6-2-1-创建对象" tabindex="-1"><a class="header-anchor" href="#_6-2-1-创建对象"><span>6.2.1 创建对象</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 方式一：使用 new Object()</span></span>
<span class="line"><span class="token keyword">let</span> obj1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Object</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方式二：使用 Object() 函数（效果相同，但 new 更明确）</span></span>
<span class="line"><span class="token keyword">let</span> obj2 <span class="token operator">=</span> <span class="token function">Object</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方式三：对象字面量（推荐，详见 6.4）</span></span>
<span class="line"><span class="token keyword">let</span> obj3 <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-2-2-操作属性的基本方法" tabindex="-1"><a class="header-anchor" href="#_6-2-2-操作属性的基本方法"><span>6.2.2 操作属性的基本方法</span></a></h3><table><thead><tr><th>操作</th><th>语法</th><th>示例</th></tr></thead><tbody><tr><td><strong>添加属性</strong></td><td><code>对象.属性名 = 属性值</code></td><td><code>obj.name = &quot;孙悟空&quot;</code></td></tr><tr><td><strong>读取属性</strong></td><td><code>对象.属性名</code></td><td><code>obj.name</code> → <code>&quot;孙悟空&quot;</code></td></tr><tr><td><strong>修改属性</strong></td><td><code>对象.属性名 = 新属性值</code></td><td><code>obj.name = &quot;猪八戒&quot;</code></td></tr><tr><td><strong>删除属性</strong></td><td><code>delete 对象.属性名</code></td><td><code>delete obj.name</code></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Object</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 添加属性</span></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>age <span class="token operator">=</span> <span class="token number">18</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>gender <span class="token operator">=</span> <span class="token string">&quot;男&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 输出：{ name: &#39;孙悟空&#39;, age: 18, gender: &#39;男&#39; }</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 读取属性</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// &quot;孙悟空&quot;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>address<span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// undefined（不存在的属性不会报错）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 修改属性</span></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;Tom sun&quot;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// &quot;Tom sun&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 删除属性</span></span>
<span class="line"><span class="token keyword">delete</span> obj<span class="token punctuation">.</span>name<span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// undefined</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-3-对象的属性" tabindex="-1"><a class="header-anchor" href="#_6-3-对象的属性"><span>6.3 对象的属性</span></a></h2><h3 id="_6-3-1-属性名的规则" tabindex="-1"><a class="header-anchor" href="#_6-3-1-属性名的规则"><span>6.3.1 属性名的规则</span></a></h3><table><thead><tr><th>属性名类型</th><th>写法</th><th>说明</th></tr></thead><tbody><tr><td><strong>普通字符串</strong></td><td><code>obj.name = &quot;孙悟空&quot;</code></td><td>建议符合标识符命名规范</td></tr><tr><td><strong>特殊字符串</strong></td><td><code>obj[&quot;属性名&quot;] = &quot;值&quot;</code></td><td>包含空格/特殊字符时使用 <code>[]</code></td></tr><tr><td><strong>变量作为属性名</strong></td><td><code>obj[变量名] = &quot;值&quot;</code></td><td>使用 <code>[]</code> 时可以动态指定属性名</td></tr><tr><td><strong>Symbol 作为属性名</strong></td><td><code>obj[symbol] = &quot;值&quot;</code></td><td>用于创建私有/唯一属性</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 1. 普通属性名（推荐）</span></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>age <span class="token operator">=</span> <span class="token number">18</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 2. 特殊属性名（不推荐，但语法允许）</span></span>
<span class="line">obj<span class="token punctuation">[</span><span class="token string">&quot;123!@#&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;特殊属性&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">[</span><span class="token string">&quot;if&quot;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;不推荐使用关键字&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 3. 使用变量作为属性名（动态属性）</span></span>
<span class="line"><span class="token keyword">let</span> key <span class="token operator">=</span> <span class="token string">&quot;address&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;花果山&quot;</span><span class="token punctuation">;</span>          <span class="token comment">// 等价于 obj[&quot;address&quot;] = &quot;花果山&quot;</span></span>
<span class="line"><span class="token comment">// obj.key = &quot;花果山&quot;      // 这会把 &quot;key&quot; 当作属性名，而不是使用变量的值</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 4. 使用 Symbol 作为属性名</span></span>
<span class="line"><span class="token keyword">const</span> mySymbol <span class="token operator">=</span> <span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">[</span>mySymbol<span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string">&quot;这是一个私有属性&quot;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">[</span>mySymbol<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;这是一个私有属性&quot;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>最佳实践</strong>：强烈建议属性名也遵循<strong>标识符命名规范</strong>（小驼峰命名法），避免使用特殊字符或关键字作为属性名。</p></blockquote><h3 id="_6-3-2-属性值" tabindex="-1"><a class="header-anchor" href="#_6-3-2-属性值"><span>6.3.2 属性值</span></a></h3><p>对象的属性值可以是<strong>任意数据类型</strong>，包括另一个对象：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">isStudent</span><span class="token operator">:</span> <span class="token boolean">true</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">score</span><span class="token operator">:</span> <span class="token number">95.5</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// 属性值可以是对象（嵌套对象）</span></span>
<span class="line">    <span class="token literal-property property">address</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">city</span><span class="token operator">:</span> <span class="token string">&quot;花果山&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">country</span><span class="token operator">:</span> <span class="token string">&quot;傲来国&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 访问嵌套对象的属性</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>address<span class="token punctuation">.</span>city<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;花果山&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-3-属性存在的检查" tabindex="-1"><a class="header-anchor" href="#_6-3-3-属性存在的检查"><span>6.3.3 属性存在的检查</span></a></h3><p>使用 <code>in</code> 运算符检查对象中是否包含某个属性：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span> <span class="token keyword">in</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// true</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;gender&quot;</span> <span class="token keyword">in</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;toString&quot;</span> <span class="token keyword">in</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true（继承自 Object 原型）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 注意：in 会检查原型链上的属性</span></span>
<span class="line"><span class="token comment">// 如果只想检查对象自身的属性，可以使用 obj.hasOwnProperty(&quot;name&quot;)</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span><span class="token function">hasOwnProperty</span><span class="token punctuation">(</span><span class="token string">&quot;name&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// true</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span><span class="token function">hasOwnProperty</span><span class="token punctuation">(</span><span class="token string">&quot;toString&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// false（原型链上的）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-3-4-类型检查" tabindex="-1"><a class="header-anchor" href="#_6-3-4-类型检查"><span>6.3.4 类型检查</span></a></h3><p>使用 <code>typeof</code> 检查对象及其属性：</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// &quot;object&quot;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;string&quot;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token keyword">typeof</span> obj<span class="token punctuation">.</span>age<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;number&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_6-4-对象的字面量-对象简写语法" tabindex="-1"><a class="header-anchor" href="#_6-4-对象的字面量-对象简写语法"><span>6.4 对象的字面量（对象简写语法）</span></a></h2><p>对象字面量是创建对象最常用、最简洁的方式，使用 <code>{}</code> 直接创建。</p><ol><li><p>基本语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">属性名</span><span class="token operator">:</span> 属性值<span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">属性名</span><span class="token operator">:</span> 属性值<span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// ...</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>代码示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> mySymbol <span class="token operator">=</span> <span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 普通属性</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span><span class="token punctuation">,</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 使用字符串作为属性名</span></span>
<span class="line">    <span class="token string-property property">&quot;gender&quot;</span><span class="token operator">:</span> <span class="token string">&quot;男&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string-property property">&quot;my-address&quot;</span><span class="token operator">:</span> <span class="token string">&quot;花果山&quot;</span><span class="token punctuation">,</span>  <span class="token comment">// 包含连字符，必须用引号</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 使用表达式作为属性名（ES6 计算属性名）</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token string">&quot;score&quot;</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token number">100</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span>mySymbol<span class="token punctuation">]</span><span class="token operator">:</span> <span class="token string">&quot;特殊的属性&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// 属性值可以是对象（嵌套）</span></span>
<span class="line">    <span class="token literal-property property">contact</span><span class="token operator">:</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token literal-property property">phone</span><span class="token operator">:</span> <span class="token string">&quot;123456789&quot;</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token literal-property property">email</span><span class="token operator">:</span> <span class="token string">&quot;sun@example.com&quot;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>contact<span class="token punctuation">.</span>phone<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;123456789&quot;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">[</span>mySymbol<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>      <span class="token comment">// &quot;特殊的属性&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><h2 id="_6-5-枚举属性-遍历对象" tabindex="-1"><a class="header-anchor" href="#_6-5-枚举属性-遍历对象"><span>6.5 枚举属性（遍历对象）</span></a></h2><p><strong>枚举（Enumerate）</strong> 指获取对象中的所有属性。使用 <strong><code>for-in</code> 语句</strong>可以遍历对象的可枚举属性。</p><ol><li><p>语法</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> propName <span class="token keyword">in</span> 对象<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// 循环体执行多次，次数等于可枚举属性的数量</span></span>
<span class="line">    <span class="token comment">// propName 依次为每个属性的名称</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li><li><p>代码示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">gender</span><span class="token operator">:</span> <span class="token string">&quot;男&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">address</span><span class="token operator">:</span> <span class="token string">&quot;花果山&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">[</span><span class="token function">Symbol</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span><span class="token operator">:</span> <span class="token string">&quot;测试&quot;</span>   <span class="token comment">// Symbol 属性默认不可枚举</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">let</span> propName <span class="token keyword">in</span> obj<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>propName<span class="token punctuation">,</span> obj<span class="token punctuation">[</span>propName<span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token comment">// 输出：</span></span>
<span class="line"><span class="token comment">// name 孙悟空</span></span>
<span class="line"><span class="token comment">// age 18</span></span>
<span class="line"><span class="token comment">// gender 男</span></span>
<span class="line"><span class="token comment">// address 花果山</span></span>
<span class="line"><span class="token comment">//（Symbol 属性不会出现在 for-in 中）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><blockquote><p><strong>注意</strong>：<code>for-in</code> 会遍历原型链上的可枚举属性。如果只想遍历对象自身的属性，可以使用 <code>Object.keys(obj)</code> 或 <code>Object.hasOwnProperty()</code> 配合 <code>for-in</code> 进行过滤。</p></blockquote><h2 id="_6-6-可变类型" tabindex="-1"><a class="header-anchor" href="#_6-6-可变类型"><span>6.6 可变类型</span></a></h2><ol><li><p>基本类型 vs 引用类型的存储方式</p><table><thead><tr><th>对比维度</th><th>原始值（不可变）</th><th>对象（可变）</th></tr></thead><tbody><tr><td><strong>存储位置</strong></td><td>值直接存储在变量中</td><td>变量存储的是<strong>内存地址</strong>（引用）</td></tr><tr><td><strong>赋值行为</strong></td><td>复制<strong>值本身</strong></td><td>复制<strong>内存地址</strong></td></tr><tr><td><strong>比较方式</strong></td><td>比较值是否相等</td><td>比较<strong>内存地址</strong>是否相同</td></tr><tr><td><strong>可变性</strong></td><td>不可变（创建后无法修改）</td><td>可变（可随时增删改属性）</td></tr></tbody></table></li><li><p>内存示意图</p><code><pre class="mermaid" id="mermaid-6wli4bp">            graph LR
    subgraph Stack[&quot;栈内存&quot;]
        S1[&quot;obj2 ➜ 0x12&quot;]
        S2[&quot;obj3 ➜ 0x34&quot;]
        S3[&quot;obj4 ➜ 0x12&quot;]
    end

    subgraph Heap[&quot;堆内存&quot;]
        H1[&quot;0x12 ➜ { name: &#39;孙悟空&#39;, age: 18 }&quot;]
        H2[&quot;0x34 ➜ { }&quot;]
    end

    S1 --&gt; H1
    S3 --&gt; H1
    S2 --&gt; H2

    style Stack fill:#e3f2fd,stroke:#1565c0
    style Heap fill:#e8f5e9,stroke:#2e7d32
    style H1 fill:#fff8e1,stroke:#f9a825
    style H2 fill:#fff8e1,stroke:#f9a825

          </pre></code></li><li><p>代码示例</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>age <span class="token operator">=</span> <span class="token number">18</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 创建两个空对象</span></span>
<span class="line"><span class="token keyword">let</span> obj2 <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token keyword">let</span> obj3 <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj2 <span class="token operator">==</span> obj3<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// false（不同的内存地址）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 将 obj 赋值给 obj4（复制的是地址）</span></span>
<span class="line"><span class="token keyword">let</span> obj4 <span class="token operator">=</span> obj<span class="token punctuation">;</span></span>
<span class="line">obj4<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;猪八戒&quot;</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj4<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;猪八戒&quot;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;猪八戒&quot;（被修改了！）</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj4 <span class="token operator">==</span> obj<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// true（指向同一个对象）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></li></ol><blockquote><p><strong>关键理解</strong>：变量存储对象时，存储的是<strong>内存地址</strong>。两个变量指向同一个对象时，通过任何一个变量修改对象，另一个变量也会受影响。</p></blockquote><h2 id="_6-7-修改属性与修改变量" tabindex="-1"><a class="header-anchor" href="#_6-7-修改属性与修改变量"><span>6.7 修改属性与修改变量</span></a></h2><h3 id="_6-7-1-修改对象-vs-修改变量" tabindex="-1"><a class="header-anchor" href="#_6-7-1-修改对象-vs-修改变量"><span>6.7.1 修改对象 vs 修改变量</span></a></h3><table><thead><tr><th>操作</th><th>代码</th><th>影响范围</th></tr></thead><tbody><tr><td><strong>修改对象属性</strong></td><td><code>obj.name = &quot;新值&quot;</code></td><td>影响所有指向该对象的变量</td></tr><tr><td><strong>修改对象引用</strong></td><td><code>obj = 新对象</code> 或 <code>obj = null</code></td><td>只影响当前变量</td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;孙悟空&#39;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">let</span> obj2 <span class="token operator">=</span> obj<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 修改对象属性 → 所有指向该对象的变量都受影响</span></span>
<span class="line">obj2<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&#39;猪八戒&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;猪八戒&quot;（obj 也变了）</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 修改变量指向 → 只影响当前变量</span></span>
<span class="line">obj2 <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">obj2<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&#39;沙和尚&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// &quot;猪八戒&quot;（obj 不受影响）</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj2<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;沙和尚&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 将变量重新赋值</span></span>
<span class="line">obj2 <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj2<span class="token punctuation">)</span><span class="token punctuation">;</span>       <span class="token comment">// null（只影响 obj2）</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">)</span><span class="token punctuation">;</span>        <span class="token comment">// { name: &#39;猪八戒&#39; }（obj 不受影响）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-7-2-使用-const-声明对象" tabindex="-1"><a class="header-anchor" href="#_6-7-2-使用-const-声明对象"><span>6.7.2 使用 <code>const</code> 声明对象</span></a></h3><p><strong>最佳实践</strong>：声明存储对象的变量时，建议使用 <code>const</code>。</p><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">const</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&#39;猪八戒&#39;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 可以修改对象的属性</span></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&#39;沙和尚&#39;</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;沙和尚&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 可以添加新属性</span></span>
<span class="line">obj<span class="token punctuation">.</span>age <span class="token operator">=</span> <span class="token number">18</span><span class="token punctuation">;</span></span>
<span class="line">console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span>obj<span class="token punctuation">.</span>age<span class="token punctuation">)</span><span class="token punctuation">;</span>   <span class="token comment">// 18</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 不能重新赋值给变量本身</span></span>
<span class="line"><span class="token comment">// obj = {};  // TypeError: Assignment to constant variable</span></span>
<span class="line"><span class="token comment">// obj = null; // TypeError: Assignment to constant variable</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>核心理解</strong>：</p><ul><li><code>const</code> 限制的是<strong>变量本身的赋值</strong>，即不能改变变量指向的内存地址</li><li><strong>对象内容（属性）的修改不受限制</strong>，因为对象本身并没有被重新创建</li></ul></blockquote><h2 id="_6-8-方法-method" tabindex="-1"><a class="header-anchor" href="#_6-8-方法-method"><span>6.8 方法（Method）</span></a></h2><p>当一个对象的属性值是一个<strong>函数</strong>时，我们称这个函数为该对象的<strong>方法（Method）</strong>。</p><h3 id="_6-8-1-方法定义" tabindex="-1"><a class="header-anchor" href="#_6-8-1-方法定义"><span>6.8.1 方法定义</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">obj<span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span>age <span class="token operator">=</span> <span class="token number">18</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 将函数赋值给对象的属性</span></span>
<span class="line">obj<span class="token punctuation">.</span><span class="token function-variable function">sayHello</span> <span class="token operator">=</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">alert</span><span class="token punctuation">(</span><span class="token string">&quot;Hello, 我是&quot;</span> <span class="token operator">+</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 调用方法（通过对象.方法名() 的方式）</span></span>
<span class="line">obj<span class="token punctuation">.</span><span class="token function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;Hello, 我是孙悟空&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-8-2-对象字面量中定义方法" tabindex="-1"><a class="header-anchor" href="#_6-8-2-对象字面量中定义方法"><span>6.8.2 对象字面量中定义方法</span></a></h3><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token keyword">let</span> person <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">age</span><span class="token operator">:</span> <span class="token number">18</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// 方法定义方式一：函数表达式</span></span>
<span class="line">    <span class="token function-variable function">sayHello</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Hello, 我是&quot;</span> <span class="token operator">+</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token comment">// 方法定义方式二：ES6 简写（推荐）</span></span>
<span class="line">    <span class="token function">sayHi</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;Hi, 我是&quot;</span> <span class="token operator">+</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">person<span class="token punctuation">.</span><span class="token function">sayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// &quot;Hello, 我是孙悟空&quot;</span></span>
<span class="line">person<span class="token punctuation">.</span><span class="token function">sayHi</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>     <span class="token comment">// &quot;Hi, 我是孙悟空&quot;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-8-3-方法和函数的区别" tabindex="-1"><a class="header-anchor" href="#_6-8-3-方法和函数的区别"><span>6.8.3 方法和函数的区别</span></a></h3><table><thead><tr><th>对比</th><th>函数（Function）</th><th>方法（Method）</th></tr></thead><tbody><tr><td><strong>定义</strong></td><td>独立定义的函数</td><td>作为对象属性的函数</td></tr><tr><td><strong>调用方式</strong></td><td><code>函数名()</code></td><td><code>对象.方法名()</code></td></tr><tr><td><strong><code>this</code> 指向</strong></td><td>取决于调用方式（严格模式/非严格模式）</td><td>指向<strong>调用该方法的对象</strong></td></tr></tbody></table><div class="language-javascript line-numbers-mode" data-highlighter="prismjs" data-ext="js"><pre><code class="language-javascript"><span class="line"><span class="token comment">// 函数</span></span>
<span class="line"><span class="token keyword">function</span> <span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;你好&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"><span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 函数调用</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// 方法</span></span>
<span class="line"><span class="token keyword">let</span> obj <span class="token operator">=</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function-variable function">greet</span><span class="token operator">:</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        console<span class="token punctuation">.</span><span class="token function">log</span><span class="token punctuation">(</span><span class="token string">&quot;你好，我是&quot;</span> <span class="token operator">+</span> <span class="token keyword">this</span><span class="token punctuation">.</span>name<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token literal-property property">name</span><span class="token operator">:</span> <span class="token string">&quot;孙悟空&quot;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line">obj<span class="token punctuation">.</span><span class="token function">greet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>  <span class="token comment">// 方法调用（通过对象调用）</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,54)])])}const i=s(e,[["render",o]]),u=JSON.parse('{"path":"/script/JavaScript/base/06.html","title":"六、对象（Object）","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790564252000,"contributors":[{"name":"zhao-farmer","username":"zhao-farmer","email":"857899180@qq.com","commits":2,"url":"https://github.com/zhao-farmer"}],"changelog":[{"hash":"cfbbc7f726ec8e4db66fff0788f0c77d25bef9b8","time":1790564252000,"email":"857899180@qq.com","author":"zhao-farmer","message":"前端代码记录"},{"hash":"c70b07d347b059fbe78c7770e7fa611a62f92633","time":1744806830000,"email":"857899180@qq.com","author":"zhao-farmer","message":"前端笔记提交"}]},"filePathRelative":"script/JavaScript/base/06.md"}');export{i as comp,u as data};
